/**
 * Fake IMOU Open API for testing without real cameras.
 *
 *   npm run fake:imou -w server          (listens on http://localhost:4555)
 *   .env:  IMOU_APP_ID=fake  IMOU_APP_SECRET=fake  IMOU_API_URL=http://localhost:4555/openapi
 *
 * Implements the calls the app uses, checks the request signature, and serves live HLS test
 * streams generated by ffmpeg (one per online camera).
 */
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';
import express from 'express';

const PORT = Number(process.env.FAKE_IMOU_PORT ?? 4555);
const SECRET = process.env.IMOU_APP_SECRET || 'fake';
const BASE = `http://localhost:${PORT}`;
const CAMS = [
  { deviceId: 'FAKE0001', name: 'Inngang', online: '1' },
  { deviceId: 'FAKE0002', name: 'Kasse', online: '1' },
  { deviceId: 'FAKE0003', name: 'Kjøkken', online: '1' },
  { deviceId: 'FAKE0004', name: 'Spisesal', online: '4' }, // dormant counts as online
  { deviceId: 'FAKE0005', name: 'Bakgård', online: '0' },
];

const ffmpeg = (() => {
  try {
    return (createRequire(import.meta.url)('ffmpeg-static') as string) || 'ffmpeg';
  } catch {
    return 'ffmpeg';
  }
})();
const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'fake-imou-'));
const procs: ReturnType<typeof spawn>[] = [];

// Live HLS test pattern per online camera, with the camera name burned in
CAMS.filter((c) => c.online !== '0').forEach((c, i) => {
  const out = path.join(dir, c.deviceId);
  fs.mkdirSync(out);
  procs.push(
    spawn(ffmpeg, [
      '-hide_banner', '-loglevel', 'error', '-re',
      '-f', 'lavfi', '-i', `testsrc2=size=640x360:rate=15`,
      '-f', 'lavfi', '-i', `sine=frequency=${300 + i * 100}:sample_rate=8000`,
      '-c:v', 'libx264', '-preset', 'ultrafast', '-tune', 'zerolatency', '-g', '30',
      '-c:a', 'aac', '-ar', '8000',
      '-f', 'hls', '-hls_time', '2', '-hls_list_size', '5', '-hls_flags', 'delete_segments',
      path.join(out, 'index.m3u8'),
    ], { stdio: 'inherit' }),
  );
  // one still image for snapshots
  spawn(ffmpeg, ['-hide_banner', '-loglevel', 'error', '-f', 'lavfi', '-i', 'testsrc2=size=640x360', '-frames:v', '1', path.join(out, 'snap.jpg')]);
});

let token = crypto.randomUUID();
const bound = new Set<string>();

const app = express();
app.use(express.json());
app.use('/live', express.static(dir));

const ok = (data: unknown = {}) => ({ result: { code: '0', msg: 'success', data } });
const fail = (code: string, msg: string) => ({ result: { code, msg } });
const streams = (id: string) =>
  [0, 1].flatMap((streamId) => [
    { streamId, status: '1', liveToken: `${id}-${streamId}`, hls: `${BASE}/live/${id}/index.m3u8` },
    { streamId, status: '1', liveToken: `${id}-${streamId}`, hls: `https://unreachable.invalid/live/${id}.m3u8` },
  ]);

app.post('/openapi/:method', (req, res) => {
  const { system, params = {} } = req.body ?? {};
  const expected = crypto.createHash('md5').update(`time:${system?.time},nonce:${system?.nonce},appSecret:${SECRET}`).digest('hex');
  if (system?.sign !== expected) return res.json(fail('SN1001', 'sign error'));
  const method = req.params.method;
  console.log('[fake-imou]', method, params.deviceId ?? '');
  if (method === 'accessToken') return res.json(ok({ accessToken: token, expireTime: 259200 }));
  if (params.token !== token) return res.json(fail('TK1002', 'token expired'));
  const cam = CAMS.find((c) => c.deviceId === params.deviceId);

  switch (method) {
    case 'deviceBaseList':
      return res.json(ok({ count: CAMS.length, deviceList: CAMS.map((c) => ({ deviceId: c.deviceId, channels: [{ channelId: '0' }] })) }));
    case 'deviceBaseDetailList':
      return res.json(ok({ deviceList: CAMS.map((c) => ({ deviceId: c.deviceId, name: c.name, channels: [{ channelId: '0', channelName: c.name }] })) }));
    case 'deviceOnline':
      return cam ? res.json(ok({ deviceId: cam.deviceId, onLine: cam.online })) : res.json(fail('DV1001', 'no device'));
    case 'getLiveStreamInfo':
      if (!cam) return res.json(fail('DV1001', 'no device'));
      return bound.has(cam.deviceId) ? res.json(ok({ streams: streams(cam.deviceId) })) : res.json(fail('LV1002', 'live not exist'));
    case 'bindDeviceLive':
      if (!cam || cam.online === '0') return res.json(fail('DV1007', 'device offline'));
      if (bound.has(cam.deviceId)) return res.json(fail('LV1001', 'live already exists'));
      bound.add(cam.deviceId);
      return res.json(ok({ liveToken: cam.deviceId, streams: streams(cam.deviceId) }));
    case 'setDeviceSnapEnhanced':
      return cam ? res.json(ok({ url: `${BASE}/live/${cam.deviceId}/snap.jpg` })) : res.json(fail('DV1001', 'no device'));
    default:
      return res.json(fail('OP1001', `fake server does not implement ${method}`));
  }
});

// Expire the token every 10 minutes to exercise the TK1002 → refresh path
setInterval(() => (token = crypto.randomUUID()), 10 * 60_000);

app.listen(PORT, () => console.log(`Fake IMOU API on ${BASE}/openapi (HLS in ${dir})`));
const stop = () => {
  procs.forEach((p) => p.kill());
  fs.rmSync(dir, { recursive: true, force: true });
  process.exit(0);
};
process.on('SIGINT', stop);
process.on('SIGTERM', stop);
